#!/usr/bin/env bash\n# scripts/setup_symlinks.sh\n# NINA Symlink Setup — one shared config propagated to all agents.\n# Run once after clone: bash scripts/setup_symlinks.sh\n# Idempotent: safe to run multiple times.\n\nset -euo pipefail\nROOT="$(cd \"$(dirname \"${BASH_SOURCE[0]}\")/..\"; pwd)"\nAGENTS_DIR="$ROOT/agents"\nCONFIG_DIR="$ROOT/config"\n\necho \"Setting up NINA config symlinks…\"\n\nSHARED_FILES=(\n    \"base_prompt.txt\"\n    \"nina_personality.json\"\n    \"token_budget.json\"\n    \"model_config.json\"\n)\n\nif [ ! -d \"$AGENTS_DIR\" ]; then\n    echo \"  agents/ directory not found — skipping.\"\nelse\n    for agent_dir in \"$AGENTS_DIR\"/*/; do\n        [ -d \"$agent_dir\" ] || continue\n        agent_name=$(basename \"$agent_dir\")\n        for fname in \"${SHARED_FILES[@]}\"; do\n            src=\"$CONFIG_DIR/$fname\"\n            dst=\"$agent_dir$fname\"\n            [ -f \"$src\" ] || continue\n            if [ -L \"$dst\" ]; then\n                echo \"  Already linked: $agent_name/$fname\"\n            elif [ -f \"$dst\" ]; then\n                echo \"  Real file exists (not symlinking): $agent_name/$fname\"\n            else\n                ln -s \"../../config/$fname\" \"$dst\"\n                echo \"  Linked: $agent_name/$fname → config/$fname\"\n            fi\n        done\n    done\nfi\n\necho \"\"\necho \"Symlink setup complete.\"\necho \"Any change to config/ now propagates to ALL agents automatically.\"\n